CREATE OR REPLACE FUNCTION public.delivery_goods_validate() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.reason_code IS NOT NULL AND NEW.reason_code NOT IN ('short','damaged','refused','other') THEN RAISE EXCEPTION 'Invalid product reason'; END IF; IF NEW.reason_code='other' AND nullif(trim(NEW.reason_note),'') IS NULL THEN RAISE EXCEPTION 'Reason note required'; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.delivery_reason_photo_register() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.trip_stops; o public.orders; BEGIN IF NEW.reason_photo_url IS NOT NULL THEN SELECT * INTO s FROM public.trip_stops WHERE id=NEW.stop_id;SELECT * INTO o FROM public.orders WHERE id=s.order_id;PERFORM public._photo_register(o.company_id,NEW.reason_photo_url,'delivery','delivery_lines',NEW.id,s.trip_id,o.customer_id,o.id,NULL,auth.uid(),now());END IF;RETURN NEW; END $$;
CREATE TRIGGER delivery_reason_photo AFTER INSERT ON public.delivery_lines FOR EACH ROW EXECUTE FUNCTION public.delivery_reason_photo_register();REVOKE ALL ON FUNCTION public.delivery_reason_photo_register() FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.delivery_diesel_validate() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.diesel_litres IS NOT NULL AND (NEW.diesel_litres<=0 OR lower(NEW.expense_type)<>'diesel') THEN RAISE EXCEPTION 'Diesel litres must be positive';END IF;RETURN NEW;END $$;
CREATE TRIGGER delivery_diesel BEFORE INSERT OR UPDATE ON public.trip_expenses FOR EACH ROW EXECUTE FUNCTION public.delivery_diesel_validate();REVOKE ALL ON FUNCTION public.delivery_diesel_validate() FROM PUBLIC,anon,authenticated;